// typed activity_stream table. Regression for issue #268: before the fix, paginated
// syncs only filled the generic resources table, so domain commands that
// query the typed table saw zero rows.
func TestUpsertBatch_PopulatesActivityStreamTable(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{"id": "test-001", "courses_id": "test-parent-001"}`),
		json.RawMessage(`{"id": "test-002", "courses_id": "test-parent-001"}`),
		json.RawMessage(`{"id": "test-003", "courses_id": "test-parent-001"}`),
	}
	if _, _, err := s.UpsertBatch("activity_stream", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}

	db := s.DB()

	var generic int
	if err := db.QueryRow(`SELECT COUNT(*) FROM resources WHERE resource_type = ?`, "activity_stream").Scan(&generic); err != nil {
		t.Fatalf("count resources: %v", err)
	}
	if generic != len(items) {
		t.Fatalf("resources count = %d, want %d", generic, len(items))
	}

	var typed int
	typedQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s"`, "activity_stream")
	if err := db.QueryRow(typedQuery).Scan(&typed); err != nil {
		t.Fatalf("count activity_stream: %v", err)
	}
	if typed != len(items) {
		t.Fatalf("activity_stream count = %d, want %d (typed table not populated by UpsertBatch)", typed, len(items))
	}
}

